# Check if any column has multiple non-background colors
input_grid = demographics[0]['input']
background = 8

color_positions = {}
for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        color = input_grid[r][c]
        if color not in color_positions:
            color_positions[color] = []
        color_positions[color].append((r, c))

# Find rows and columns with multiple non-background colors
non_bg = [c for c in color_positions if c != background]

print("Rows with multiple non-background colors:")
for r in range(len(input_grid)):
    row_colors = set(color_positions[c][i] for c in non_bg for i, _ in enumerate(color_positions[c]) if r == color_positions[c][i][0])
    # Actually simpler:
    row_colors = set()
    for c in non_bg:
        if r in [pos[0] for pos in color_positions[c]]:
            row_colors.add(c)
    if len(row_colors) > 1:
        print(f"  Row {r}: {sorted(row_colors)}")

print("\nColumns with multiple non-background colors:")
for c in range(len(input_grid[0])):
    col_colors = set()
    for row_c in non_bg:
        if c in [pos[1] for pos in color_positions[row_c]]:
            col_colors.add(row_c)
    if len(col_colors) > 1:
        print(f"  Col {c}: {sorted(col_colors)}")

# Now I see the template row! Row 12 has both colors 4 and 0

# The template pattern is [input_grid[12][13], input_grid[12][14], ..., input_grid[12][17]]
template_pattern = [input_grid[12][13+c] for c in range(5)]
print(f"\nTemplate pattern from row 12 cols 13-17: {template_pattern}")

